// src/pages/Login.jsx
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { login } from "../services/api";
import "./Login.css";

export default function Login() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      await login(username, password);
      navigate("/dashboard");
    } catch (err) {
      setError(err.message || "Credenciales incorrectas");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-fullscreen">
      {/* Tu foto de fondo aquí */}
      <div className="background-image"></div>

      {/* Overlay rojo elegante */}
      <div className="red-overlay"></div>

      {/* Contenido centrado – sin cuadro, todo flota */}
      <div className="login-content">
        <h1 className="title">SOFTFOOD</h1>
        <p className="subtitle">Sistema de Gestión</p>

        <form onSubmit={handleSubmit} className="login-form">
          <input
            type="text"
            placeholder="USUARIO"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="CONTRASEÑA"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />

          {error && <p className="error">{error}</p>}

          <button type="submit" disabled={loading} className="btn-login">
            {loading ? "INGRESANDO..." : "INGRESAR"}
          </button>
        </form>

        <p className="demo">
          Demo: <strong>admin</strong> / <strong>12345</strong>
        </p>
      </div>
    </div>
  );
}
